      "policy_source_id": "q15",
      "policy_quote": "- You can act only through the tools in [AVAILABLE TOOLS]. The list is complete; there are no other tools.",
      "requirement": "The action must be executed exclusively using the **transfer_ticket** tool, and no other tools or methods may be used for this purpose."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "- transfer_ticket — Change the name on a ticket.",
      "requirement": "The **transfer_ticket** tool must be used to change the name on a ticket, and the action must strictly adhere to its defined purpose."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "You help customers with ticket orders: seat exchanges, refunds, name transfers and delivery of e-tickets.",
      "requirement": "The action must be related to **name transfers** for tickets, and no other unrelated actions (e.g., resale listings, accessibility seating changes) may be performed."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "- transfer_ticket — Change the name on a ticket.\n    order_id: string! — Order ID.\n    ticket_id: string! — Ticket ID.\n    new_name: string! — New holder name.",
      "requirement": "The **transfer_ticket** tool call must include **all required arguments**: `order_id`, `ticket_id`, and `new_name`, and they must be provided in the exact format specified (e.g., `order_id` must match the order ID format)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "You cannot do both [send a message to the user and make a tool call] at the same time.",
      "requirement": "The action must be performed **without** sending a message to the user simultaneously; tool calls must be made independently of user communication."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "Always communicate with the user in Russian.",
      "requirement": "If any communication (e.g., confirmation or explanation) is required before or after the tool call, it must be conducted **exclusively in Russian**."
    }
  ]
}
